const e="bresil",l=1,s={habitants:"les Brésiliens",adjectif:"brésilien",adjectifF:"brésilienne",devise:"Ordem e Progresso, sous réserve de la coalition du jeudi.",medaillon:"BR",chaineInfo:"BR NOTÍCIAS",hymne:"Ouvi do Ipiranga : version raccourcie pour cause de pluie"},n={chambre:"Congrès",chambreLong:"Congrès national",chefGouvernement:"Président de la République fédérative",chefEtat:"Président de la République fédérative",passageForce:{label:"Mesure provisoire",description:"Le président publie une mesure qui a force de loi pendant plusieurs semaines, le temps que le Congrès la confirme, l’amende ou la laisse mourir. L’exécutif adore ce délai, le Congrès l’adore moins.",news:"Mesure provisoire : « {loi} » entre en vigueur en attendant la bénédiction du Congrès"},censure:{label:"Procédure de destitution",description:"La Chambre autorise la mise en cause du président, le Sénat décide de la destitution. Une procédure longue, tendue, dont tout le monde se souvient mais que personne ne souhaite revivre.",news:"Procédure de destitution : le Congrès sort les dossiers, le palais sort les avocats"},dissolution:{label:"Appel au peuple et plébiscite",description:"Le président sollicite le soutien direct de la population par une tournée et un grand rassemblement. Le Congrès n’est pas dissous, mais il se montre très attentif aux sondages.",news:"Appel au peuple : le président s’adresse à la nation, le Congrès relit les sondages"}},t={type:"presidentielle",label:"Élection présidentielle",intro:"Deux tours, des dizaines de candidats au premier, des alliances à la carte et un horaire de campagne télévisée que les écoles de samba envieraient. Les caravanes parcourent un pays-continent en distribuant des tracts et des jingles.",adversaires:[{id:"albano-ferraz",name:"Albano Ferraz",parti:"Parti Libéral du Brésil",style:"attaque",punchlines:["Mon adversaire promet le paradis, mais l’inflation est déjà arrivée avant lui.","Nous sommes un pays d’agriculteurs, d’entrepreneurs et de gens qui travaillent. Les autres sont des gens qui commentent.","Le gouvernement a plus de ministères que d’idées, c’est un exploit."],genre:"m"},{id:"beatriz-amaral",name:"Beatriz Amaral",parti:"Parti des Travailleurs Unis",style:"emotion",punchlines:["Un pays qui ne nourrit pas ses enfants n’a pas le droit de se dire grand.","J’ai vu les écoles de mon État, j’ai vu les sourires. Ils ne demandent pas des miracles, juste des repas.","Ils ont des idées pour les marchés, moi j’ai des idées pour les marmites."],genre:"f"},{id:"caio-menezes",name:"Caio Menezes",parti:"Union du Centre Large",style:"esquive",punchlines:["Je suis du centre, c’est-à-dire de partout et de nulle part.","Mon programme est flexible, mon agenda l’est plus encore.","Je ne vous promets rien, c’est la meilleure façon de ne pas vous décevoir."],genre:"m"}],nuitElectorale:"Les urnes électroniques livrent leur verdict en quelques heures, ce qui laisse peu de temps pour inventer des explications. Sur l’avenue Paulista, les klaxons répondent aux feux d’artifice."},a=[{id:"bresil-reforme-fiscale-simplif",title:"Simplification de la fiscalité sur la consommation",domain:"travail",description:"Fusionner cinq taxes en une seule, dont personne ne comprendra le taux. Les comptables protestent poliment, les entreprises dansent la samba de l’espoir.",accroche:"Une seule taxe au lieu de cinq : on garde les quatre autres en souvenir.",effects:{economie:5,budget:2,pouvoirAchat:-2,popularite:-2},delayed:[{delay:4,effects:{economie:3,budget:2},label:"Moins de paperasse, plus d’investissement"}],groupStance:{trabalhadores:.3,"liberal-brasil":.7,"centrao-uniao":.5,"progressistas-br":.4,"mdb-democratico":.6,"verdes-amazonia":-.1,"socialistas-br":.2},streetAnger:.3},{id:"bresil-amazonie-protection",title:"Plan de protection de l’Amazonie",domain:"ecologie",description:"Renforcer la surveillance, les amendes et les satellites pour freiner la déforestation. Les arbres applaudissent en silence, les exploitants applaudissent moins.",accroche:"La forêt demande qu'on la protège, les arbres signent des deux mains.",effects:{ecologie:7,international:3,economie:-3,popularite:-2},delayed:[{delay:3,effects:{ecologie:2,international:2},label:"Déforestation en recul"},{delay:4,effects:{economie:-1,cohesion:-1},label:"Tensions avec les exploitants"}],groupStance:{trabalhadores:.6,"liberal-brasil":-.9,"centrao-uniao":.1,"progressistas-br":.1,"mdb-democratico":.2,"verdes-amazonia":1,"socialistas-br":.7},streetAnger:.4},{id:"bresil-bourse-famille-renforcee",title:"Allocation familiale renforcée",domain:"travail",description:"Augmenter le montant d’une allocation qui touche des dizaines de millions de foyers. Les économistes demandent comment la financer, les foyers demandent quand.",accroche:"Plus d'aide aux familles, et le même nombre de réunions pour la comprendre.",effects:{pouvoirAchat:5,cohesion:3,budget:-6,popularite:3},delayed:[{delay:3,effects:{pouvoirAchat:1,cohesion:1},label:"Consommation locale stimulée"}],groupStance:{trabalhadores:1,"liberal-brasil":-.6,"centrao-uniao":.4,"progressistas-br":.6,"mdb-democratico":.3,"verdes-amazonia":.4,"socialistas-br":.9},streetAnger:.2},{id:"bresil-agrobusiness-credit",title:"Crédit agricole à taux préférentiel",domain:"agriculture",description:"Des prêts à taux réduits pour l’agriculture exportatrice. Les silos se remplissent, la Banque publique aussi se remplit, d’obligations.",accroche:"Un crédit pour les champs : le soja pousse, la dette suit gentiment à côté.",effects:{economie:5,budget:-5,ecologie:-3,international:2},delayed:[{delay:3,effects:{economie:2,international:1},label:"Records de récolte"}],groupStance:{trabalhadores:-.4,"liberal-brasil":1,"centrao-uniao":.6,"progressistas-br":.6,"mdb-democratico":.5,"verdes-amazonia":-.9,"socialistas-br":-.5},streetAnger:.2},{id:"bresil-securite-favelas-police",title:"Programme de police de proximité dans les quartiers défavorisés",domain:"securite",description:"Quatre mille agents formés à écouter avant de tirer, ce qui change les habitudes. Les habitants attendent de voir, les chaînes d’information attendent de filmer.",accroche:"Des policiers qui connaissent les prénoms plutôt que les numéros de dossier.",effects:{securite:5,cohesion:3,budget:-5,popularite:-1},delayed:[{delay:4,effects:{securite:2,cohesion:2},label:"Moins d’affrontements"}],groupStance:{trabalhadores:.7,"liberal-brasil":.2,"centrao-uniao":.4,"progressistas-br":.5,"mdb-democratico":.4,"verdes-amazonia":.3,"socialistas-br":.6},streetAnger:.3},{id:"bresil-carburants-prix-controle",title:"Plafonnement des prix des carburants",domain:"energie",description:"Plafonner les prix à la pompe pour contenir l’inflation. La compagnie publique subventionne le litre et rembourse sa dette à la loterie.",accroche:"Le litre plafonné rassure la pompe, mais fait pleurer le tableau des marges.",effects:{pouvoirAchat:5,popularite:3,budget:-6,economie:-2},delayed:[{delay:3,effects:{budget:-2,economie:-1},label:"Subvention qui coûte cher"}],groupStance:{trabalhadores:.6,"liberal-brasil":-.7,"centrao-uniao":.4,"progressistas-br":.5,"mdb-democratico":.4,"verdes-amazonia":-.6,"socialistas-br":.6},streetAnger:.2},{id:"bresil-education-temps-plein",title:"École à temps plein",domain:"education",description:"Garder les enfants à l’école toute la journée avec repas, sport et orchestre de percussions. Les instituteurs veulent des postes, les parents veulent des repas.",accroche:"L'école ouvre toute la journée, y compris pour ceux qui voulaient une sieste.",effects:{cohesion:4,pouvoirAchat:2,budget:-6,popularite:2},delayed:[{delay:4,effects:{cohesion:2,economie:1},label:"Décrochage en baisse"}],groupStance:{trabalhadores:.9,"liberal-brasil":-.2,"centrao-uniao":.5,"progressistas-br":.6,"mdb-democratico":.5,"verdes-amazonia":.4,"socialistas-br":.9},streetAnger:.1},{id:"bresil-sante-sus-modernisation",title:"Modernisation du système de santé universel",domain:"sante",description:"Mettre à jour un système de santé universel déjà admiré dans le monde. Les files d’attente se raccourcissent, les cadres administratifs s’allongent.",accroche:"La santé pour tous sera désormais accessible, avec numéro d'attente en couleurs.",effects:{cohesion:4,pouvoirAchat:1,budget:-5,popularite:2},delayed:[{delay:3,effects:{cohesion:2,popularite:1},label:"Délais réduits"}],groupStance:{trabalhadores:.9,"liberal-brasil":-.4,"centrao-uniao":.5,"progressistas-br":.6,"mdb-democratico":.6,"verdes-amazonia":.5,"socialistas-br":.8},streetAnger:.1},{id:"bresil-indemnites-parlementaires",title:"Réforme des amendements budgétaires parlementaires",domain:"institutions",description:"Plafonner les fonds que les élus orientent vers leurs circonscriptions. Les élus sont d’accord à condition que le plafond soit plus haut que les leurs.",accroche:"Les amendements budgétaires passent au grand jour, ce qui les rend timides.",effects:{assemblee:-5,budget:3,cohesion:2,popularite:2},delayed:[{delay:4,effects:{assemblee:1,budget:1},label:"Négociations rétablies par d’autres moyens"}],groupStance:{trabalhadores:.4,"liberal-brasil":-.1,"centrao-uniao":-.9,"progressistas-br":-.7,"mdb-democratico":-.6,"verdes-amazonia":.5,"socialistas-br":.6},streetAnger:.2},{id:"bresil-transport-rail-fret",title:"Plan ferroviaire pour le fret",domain:"energie",description:"Poser des rails pour que les récoltes voyagent autrement qu’en camion. Dans un pays où les distances ont un accent, c’est un projet à très long terme.",accroche:"Les camions regardent passer les wagons, partagés entre admiration et lumière rouge.",effects:{economie:4,ecologie:2,budget:-6,cohesion:1},delayed:[{delay:4,effects:{economie:3,ecologie:1},label:"Premières lignes ouvertes"}],groupStance:{trabalhadores:.4,"liberal-brasil":.6,"centrao-uniao":.6,"progressistas-br":.5,"mdb-democratico":.6,"verdes-amazonia":.3,"socialistas-br":.2},streetAnger:.1}],i=JSON.parse('[{"id":"bresil-incendies-amazonie","title":"Incendies en Amazonie","category":"climat","description":"Les feux dessinent une carte fumante au-dessus de la forêt. Les satellites comptent, les avions épandent, les ONG bondissent et les exploitants démentent tout ce qui ressemble à une allumette.","weight":7,"minTurn":3,"conditions":[{"gauge":"ecologie","op":"<","value":66}],"choices":[{"id":"fiscalisation","label":"Déployer les agences environnementales et l’armée","description":"Éteindre, arrêter, amender.","effects":{"ecologie":5,"international":3,"popularite":-2,"budget":-5,"securite":1},"delayed":[{"delay":3,"effects":{"ecologie":2,"international":2},"label":"Coopération internationale rétablie"}],"news":"Amazonie : l’armée et les inspecteurs entrent dans la forêt"},{"id":"fonds-international","label":"Accepter un fonds international","description":"Un chèque étranger contre des garanties de surveillance.","effects":{"international":3,"ecologie":3,"popularite":-2,"budget":3},"delayed":[{"delay":3,"effects":{"international":1,"popularite":-1},"label":"Débat sur la souveraineté"}],"news":"Fonds Amazonie : les donateurs applaudissent, les nationalistes grincent"},{"id":"minimiser","label":"Minimiser les chiffres","description":"Dire que la saison est « normale » et que les données sont « interprétées ».","effects":{"popularite":1,"economie":1,"ecologie":-5,"international":-4},"delayed":[{"delay":3,"effects":{"popularite":-3,"international":-2},"label":"Boycott de produits"}],"chain":{"crisisId":"bresil-sanctions-commerciales-forets","probability":0.4,"delay":2},"news":"Amazonie : l’exécutif parle d’exagération, la fumée arrive à São Paulo"}]},{"id":"bresil-sanctions-commerciales-forets","title":"Boycott des produits issus de la déforestation","category":"international","description":"Des acheteurs étrangers menacent de refuser le soja et le bœuf traçables comme un météore. Les exportateurs promettent des certificats, les certificats promettent des problèmes.","weight":5,"chainOnly":true,"choices":[{"id":"tracabilite","label":"Imposer la traçabilité","description":"Un système de suivi de la ferme à l’assiette.","effects":{"international":3,"ecologie":3,"economie":-2,"budget":-3},"delayed":[{"delay":3,"effects":{"economie":2,"international":2},"label":"Contrats sauvés"}],"news":"Traçabilité obligatoire : les vaches ont désormais une identité numérique"},{"id":"contre-attaque","label":"Dénoncer le protectionnisme vert","description":"Un discours enflammé devant les agriculteurs.","effects":{"popularite":2,"international":-3,"economie":-3,"cohesion":1},"delayed":[{"delay":3,"effects":{"economie":-2},"label":"Perte de marchés"}],"news":"Le Brésil dénonce un « colonialisme climatique »"}]},{"id":"bresil-carnaval-depenses","title":"Carnaval et accidents","category":"social","description":"Le carnaval déborde sur les budgets de sécurité, de nettoyage et d’ambulances. Les écoles de samba réclament des fonds, la mairie réclame des excuses et la sécurité réclame un miracle.","weight":6,"minTurn":3,"choices":[{"id":"subvention-festive","label":"Financer les écoles et les défilés","description":"Un soutien public à la culture populaire.","effects":{"cohesion":4,"popularite":3,"budget":-5,"economie":1},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Tourisme record"}],"news":"Carnaval : le gouvernement finance les plumes et les tambours"},{"id":"securite-renfort","label":"Renforcer le dispositif de sécurité","description":"Plus de policiers, plus de caméras, moins de confettis.","effects":{"securite":3,"budget":-4,"cohesion":-1,"popularite":-1},"news":"Carnaval sous haute surveillance : la police danse, mais en uniforme"},{"id":"sobre","label":"Imposer un carnaval sobre","description":"Moins de dépenses, plus de rigueur, moins de joie.","effects":{"budget":3,"popularite":-5,"cohesion":-3},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Ambiance d’enterrement"}],"news":"Carnaval « sobre » annoncé : les cortèges se contentent d’une fanfare"}]},{"id":"bresil-inflation-aliments","title":"Flambée du prix des aliments","category":"economie","description":"Le prix du haricot noir, du riz et du café monte plus vite que la samba. Les ménages font les comptes, les supermarchés font des promotions et le gouvernement fait des communiqués.","weight":7,"minTurn":3,"conditions":[{"gauge":"pouvoirAchat","op":"<","value":52}],"choices":[{"id":"stocks","label":"Libérer les stocks publics","description":"Vendre à prix réduit les réserves de céréales.","effects":{"pouvoirAchat":4,"popularite":2,"budget":-5},"delayed":[{"delay":3,"effects":{"budget":-1},"label":"Stocks à reconstituer"}],"news":"Stocks publics libérés : le riz redevient un sujet de conversation courtois"},{"id":"taux","label":"Relever les taux directeurs","description":"Refroidir l’économie pour calmer les prix.","effects":{"pouvoirAchat":-3,"economie":-3,"budget":2,"international":2,"popularite":-3},"delayed":[{"delay":3,"effects":{"pouvoirAchat":2,"economie":1},"label":"Inflation freinée"}],"news":"Taux relevés : la banque centrale a une opinion, les ménages en ont une autre"},{"id":"accord-prix","label":"Négocier un pacte avec la grande distribution","description":"Faire plaisir à tout le monde sans fâcher personne.","effects":{"pouvoirAchat":2,"popularite":1,"cohesion":1},"delayed":[{"delay":3,"effects":{"pouvoirAchat":-1},"label":"Promesses éphémères"}],"news":"Pacte des prix : la grande distribution s’engage solennellement, avec rabais"}]},{"id":"bresil-coalition-circonstance","title":"La Coalition du Jeudi se délite","category":"politique","description":"La majorité de circonstance formée le jeudi précédent s’est déjà défaite le lundi. Les élus réclament des ministères, des fonds, une photo avec le président et, de préférence, les trois.","weight":7,"minTurn":3,"conditions":[{"gauge":"assemblee","op":"<","value":48}],"choices":[{"id":"ministeres","label":"Distribuer des ministères","description":"Un portefeuille contre quelques votes.","effects":{"assemblee":5,"popularite":-3,"budget":-3,"cohesion":-1},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Coalition en perpétuelle renégociation"}],"news":"Remaniement-surprise : trois nouveaux ministres et une nouvelle coalition"},{"id":"amendements","label":"Débloquer les fonds d’amendements","description":"Financer les circonscriptions des alliés.","effects":{"assemblee":4,"budget":-5,"popularite":-1},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Scandale des gros travaux"}],"news":"Fonds débloqués : les circonscriptions retrouvent le goût des travaux"},{"id":"mesure-provisoire","label":"Gouverner par mesure provisoire","description":"Contourner le Congrès, qui y verra un affront.","effects":{"assemblee":-4,"popularite":1,"economie":1,"cohesion":-1},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Retour de bâton parlementaire"}],"news":"Mesure provisoire signée : le Congrès fait mine de ne pas se vexer"}]},{"id":"bresil-secheresse-nordeste","title":"Sécheresse dans le Nord-Est","category":"climat","description":"Les réservoirs sont vides, le bétail maigrit et les camions-citernes remplacent les rivières. Les élus de la région rappellent qu’ils ont voté pour la dernière fois en pensant à l’eau.","weight":5,"minTurn":4,"choices":[{"id":"citernes","label":"Envoyer des camions-citernes et des aides alimentaires","description":"Une réponse immédiate.","effects":{"cohesion":3,"budget":-5,"popularite":2},"delayed":[{"delay":3,"effects":{"cohesion":1},"label":"Villages ravitaillés"}],"news":"Nord-Est : citernes et paniers repas arrivent dans les villages"},{"id":"canal","label":"Relancer un grand canal de transposition","description":"Un chantier colossal et très médiatique.","effects":{"ecologie":-1,"economie":2,"budget":-6,"popularite":2},"delayed":[{"delay":4,"effects":{"ecologie":1,"cohesion":2},"label":"Premières eaux livrées"}],"news":"Canal de transposition : on creuse, on inaugure, on recommence"},{"id":"assurance-s","label":"Créer un fonds d’assurance climatique","description":"Indemniser les petits exploitants.","effects":{"cohesion":2,"economie":1,"budget":-3,"ecologie":1},"news":"Fonds d’assurance climatique : un formulaire par buffle"}]},{"id":"bresil-greve-camionneurs","title":"Grève des camionneurs","category":"economie","description":"Les camionneurs bloquent les routes pour protester contre le diesel, les péages et la fatigue. Les rayons se vident, les stations-service organisent des loteries et l’autoroute devient un parking.","weight":5,"minTurn":4,"choices":[{"id":"concessions-d","label":"Accorder une aide et un gel du prix du diesel","description":"Débloquer les routes en payant.","effects":{"economie":2,"popularite":1,"budget":-6,"pouvoirAchat":1},"delayed":[{"delay":3,"effects":{"budget":-2},"label":"Facture de l’accord"}],"news":"Grève des camionneurs : accord signé sur un capot"},{"id":"reprise-force","label":"Faire dégager les routes","description":"Rétablir la circulation par la force.","effects":{"securite":2,"economie":1,"popularite":-4,"cohesion":-3},"delayed":[{"delay":3,"effects":{"cohesion":-1},"label":"Rancœur durable"}],"news":"Routes dégagées : camionneurs en colère, klaxons en chœur"},{"id":"mediation","label":"Nommer un médiateur","description":"Un sage, une table et des dizaines de cafés.","effects":{"popularite":-1,"cohesion":1,"economie":-2},"delayed":[{"delay":3,"effects":{"economie":1,"cohesion":1},"label":"Accord partiel"}],"news":"Médiation : le médiateur boit son troisième café"}]},{"id":"bresil-peuples-indigenes-terres","title":"Démarcation des terres indigènes","category":"politique","description":"Des peuples autochtones réclament la démarcation de leurs terres, les exploitants réclament des études complémentaires et le Congrès réclame un calendrier flou.","weight":4,"minTurn":5,"choices":[{"id":"demarquer","label":"Signer les décrets de démarcation","description":"Reconnaître les terres, avec les cartes à l’appui.","effects":{"cohesion":2,"ecologie":3,"international":2,"assemblee":-3,"economie":-1},"delayed":[{"delay":3,"effects":{"assemblee":-1},"label":"Recours parlementaires"}],"news":"Terres indigènes reconnues : cartographes et juristes à l’œuvre"},{"id":"delai","label":"Commander des études supplémentaires","description":"Gagner du temps, perdre de la crédibilité.","effects":{"popularite":-3,"cohesion":-2,"assemblee":1},"news":"Études supplémentaires commandées : trois ans de plus à l’horizon"},{"id":"compromis-t","label":"Négocier une solution mixte","description":"Reconnaître certaines terres, en partager d’autres.","effects":{"cohesion":1,"assemblee":1,"ecologie":1,"popularite":-1},"news":"Solution mixte : personne n’est vraiment content, tout le monde reste à table"}]}]'),r=[{id:"bresil-coalition-tient",title:"Maintenir la majorité de circonstance",brief:"Un indice d’assemblée à 50 : une coalition qui dure plus longtemps que la précédente, soit un record.",objective:{type:"gaugeAtLeast",gauge:"assemblee",value:50},reward:{assemblee:2,popularite:1},news:"Congrès : la coalition survit à une semaine, un record historique"},{id:"bresil-amazonie-sauvee",title:"Soigner la forêt",brief:"Un indice d’écologie à 65 : un trimestre sans polémique sur les cendres.",objective:{type:"gaugeAtLeast",gauge:"ecologie",value:65},reward:{ecologie:2,international:1},news:"Amazonie : le satellite signale moins de fumée, l’ONG envoie un communiqué sobre"},{id:"bresil-inflation-maitrisee",title:"Rendre le panier moins cher",brief:"Gagner quatre points de pouvoir d’achat : faire cesser les conversations sur le prix des haricots.",objective:{type:"gaugeGain",gauge:"pouvoirAchat",value:4},reward:{pouvoirAchat:2,popularite:1},news:"Inflation : le panier de base recule, les supermarchés parlent de « geste commercial »"},{id:"bresil-mesure-provisoire-validee",title:"Faire adopter une loi sans trop d’amendements",brief:"Un texte voté avant la fin du trimestre, par n’importe quelle coalition du jeudi.",objective:{type:"lawAdopted"},reward:{assemblee:2,popularite:1},news:"Congrès : la loi passe, les amendements prennent un verre"}],o=JSON.parse('{"medias":["Le Diário du Cerrado","Rádio Capivara FM","Canal Brasa 24h","Gazeta da Várzea","La Voix du Sertão"],"journalistes":[{"id":"bresil-j-tavares","name":"Mariana Tavares-Coelho","media":"Le Diário du Cerrado","style":"incisif : relance en portugais, puis en français, puis avec un graphique","genre":"f"},{"id":"bresil-j-pestana","name":"Rodrigo Pestana","media":"Canal Brasa 24h","style":"alarmiste : un bandeau rouge pour chaque nuage au-dessus de Brasilia","genre":"m"},{"id":"bresil-j-bittencourt","name":"Luciana Bittencourt","media":"Le Diário du Cerrado","style":"économiste : parle de taux d’intérêt comme d’une météo","genre":"f"},{"id":"bresil-j-lobo","name":"Tiago Ferreira Lobo","media":"Rádio Capivara FM","style":"provocateur : pose sa question piégée au moment du but","genre":"m"},{"id":"bresil-j-camargo","name":"Zélia Camargo","media":"Gazeta da Várzea","style":"maternelle : demande si vous avez mangé avant de vous mettre en colère","genre":"f"},{"id":"bresil-j-rios","name":"Gustavo Andrade-Rios","media":"La Voix du Sertão","style":"terrien : ne croit qu’aux chiffres de la pluie et aux promesses écrites","genre":"m"},{"id":"bresil-j-quintela","name":"Fernanda Quintela","media":"Canal Brasa 24h","style":"enquêtrice : arrive avec un dossier, des pièces jointes et un café","genre":"f"},{"id":"bresil-j-moura","name":"Hélio Moura-Santana","media":"Rádio Capivara FM","style":"complaisant : commence toujours par « vous avez l’air en forme »","genre":"m"}],"questions":[{"id":"bresil-q-sondage-bas","theme":"popularite","condition":{"gauge":"popularite","op":"<","value":40},"text":"Chef de l’exécutif, votre cote tombe plus vite qu’un pénalty mal tiré. Les Brésiliens vous ont-ils déjà sifflé en bas de chez vous ?","answers":[{"tone":"franche","label":"On m’a sifflé, oui, et j’ai trouvé que le rythme était bon. Je n’ai pas besoin d’applaudissements, mais de résultats que l’on puisse mesurer.","effects":{"popularite":4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les alliés se rapprochent des sorties"}],"news":"Sondages : le président brésilien admet avoir été sifflé"},{"tone":"langue-de-bois","label":"Un pays-continent ne se juge pas à une photographie. Les chiffres du Nord, du Sud et du centre racontent une histoire d’ensemble que je vous invite à lire.","effects":{"popularite":2,"economie":-2},"news":"Cote en baisse : le Planalto invoque « l’histoire d’ensemble »"},{"tone":"offensive","label":"Ceux qui sifflent le plus fort sont ceux qui n’ont jamais joué un match. Je les invite sur le terrain, avec un vrai programme.","effects":{"popularite":5,"cohesion":-3,"international":-2},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Les caméras ont tout filmé"}],"news":"Le président brésilien renvoie les siffleurs sur le terrain"}]},{"id":"bresil-q-selic-haute","theme":"economie","condition":{"gauge":"economie","op":"<","value":45},"text":"Les taux d’intérêt sont si hauts que même le crédit pour le café du matin demande un apport. Les entrepreneurs vous demandent quand la banque centrale cessera de jouer les gardiens de but.","answers":[{"tone":"franche","label":"La banque centrale est indépendante, et c’est tant mieux. Mais je lui dirai ce que vous endurez : le crédit cher étouffe l’emploi.","effects":{"economie":4,"international":-2},"delayed":[{"delay":2,"effects":{"budget":-2},"label":"Les marchés froncent les sourcils"}],"news":"Taux d’intérêt : le président brésilien interpelle la banque centrale"},{"tone":"langue-de-bois","label":"Nous suivons la trajectoire avec attention, dans un esprit de responsabilité partagée et de dialogue avec toutes les parties prenantes.","effects":{"economie":2,"popularite":-2},"news":"Taux : « responsabilité partagée », répond le Planalto"},{"tone":"offensive","label":"Quand le crédit coûte une fortune, c’est qu’il sert d’abord les rentiers. J’en ai assez de financer la rente avec la sueur des autres.","effects":{"economie":3,"popularite":4,"international":-3,"budget":-2},"delayed":[{"delay":3,"effects":{"economie":-2},"label":"Le real hésite sur les marchés"}],"news":"Le président s’en prend aux « rentiers » : la Bourse tousse"}]},{"id":"bresil-q-emendas","theme":"budget","condition":{"gauge":"budget","op":"<","value":40},"text":"Les amendements budgétaires du Congrès prélèvent chaque année une part gigantesque du budget, distribuée à coups de pont et de dispensaire. Le chef de l’exécutif a-t-il encore la main sur la caisse ?","answers":[{"tone":"franche","label":"Pas autant qu’il le faudrait. Je veux des règles claires et publiques : chaque réal d’amendement doit avoir un nom, un lieu et un contrôle.","effects":{"budget":4,"assemblee":-3},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Le Congrès ralentit les votes"}],"news":"Amendements : le président veut que chaque réal ait un nom"},{"tone":"langue-de-bois","label":"Le dialogue constructif entre les pouvoirs est la clé. Nous trouverons un équilibre responsable, dans le respect de l’architecture institutionnelle.","effects":{"assemblee":2,"budget":-2},"news":"Amendements : un « équilibre responsable » promis, sans chiffres"},{"tone":"offensive","label":"Un pays où le trésor se distribue par amendement est un pays qui s’administre à la brouette. Je ne signerai plus de chèques en blanc.","effects":{"budget":5,"popularite":2,"assemblee":-5},"delayed":[{"delay":2,"effects":{"assemblee":-3,"cohesion":-1},"label":"Le Congrès bloque deux projets en représailles"}],"news":"Chèques en blanc : le président défie la « caisse du Congrès »"}]},{"id":"bresil-q-prix-haricot","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":42},"text":"Le haricot noir, le riz et le café coûtent plus cher à chaque passage en caisse. À partir de quel prix du feijão un gouvernement perd-il le déjeuner de ses électeurs ?","answers":[{"tone":"franche","label":"Il est déjà franchi. Les familles font des calculs que personne ne devrait faire, et j’ai demandé un plan de stocks et de transport immédiat.","effects":{"pouvoirAchat":4,"budget":-3},"delayed":[{"delay":3,"effects":{"pouvoirAchat":2},"label":"Les étals respirent un peu mieux"}],"news":"Cherté des aliments : le président annonce un plan de stocks"},{"tone":"langue-de-bois","label":"L’alimentation reste une priorité structurante. Nous agirons sur toute la chaîne de valeur, du champ à l’assiette, avec méthode.","effects":{"pouvoirAchat":2,"popularite":-2},"news":"« Du champ à l’assiette » : le Planalto promet de la méthode"},{"tone":"offensive","label":"Quand le pays exporte du soja par navires entiers et que le haricot manque, il y a des intermédiaires à interroger. Les marges seront contrôlées.","effects":{"pouvoirAchat":3,"popularite":3,"economie":-4},"delayed":[{"delay":2,"effects":{"economie":-2,"international":-1},"label":"Les grands distributeurs montent au créneau"}],"news":"Le président attaque les marges des intermédiaires"}]},{"id":"bresil-q-favelas-police","theme":"securite","condition":{"gauge":"securite","op":"<","value":40},"text":"Dans certains quartiers, la police et les gangs se disputent le même carrefour. Faut-il envoyer plus d’uniformes, ou plus d’écoles, ou les deux et un miracle ?","answers":[{"tone":"franche","label":"Les deux, et sans miracle. Une police de proximité qui connaît les rues, des écoles ouvertes toute la journée, et des résultats mesurés tous les trimestres.","effects":{"securite":4,"budget":-3},"delayed":[{"delay":3,"effects":{"securite":2,"cohesion":1},"label":"Le premier quartier-test signale une baisse"}],"news":"Quartiers difficiles : « des écoles et des patrouilles », dit le président"},{"tone":"langue-de-bois","label":"La sécurité est l’affaire de tous. Une approche intégrée, transversale et territorialisée nous permettra d’agir sur les causes comme sur les effets.","effects":{"securite":2,"popularite":-2},"news":"Sécurité : une « approche territorialisée », sans carte précise"},{"tone":"offensive","label":"Les honnêtes gens des quartiers n’ont pas à attendre qu’un séminaire se termine. Plus de moyens aux forces de l’ordre, et dès cette semaine.","effects":{"securite":5,"popularite":3,"cohesion":-4},"delayed":[{"delay":2,"effects":{"cohesion":-2,"international":-1},"label":"Des associations dénoncent une méthode brutale"}],"news":"Le président annonce un renfort policier immédiat"}]},{"id":"bresil-q-nordeste-sud","theme":"cohesion","condition":{"gauge":"cohesion","op":"<","value":42},"text":"Le Nord-Est dit qu’on l’oublie, le Sud dit qu’il paie pour tous, l’Amazonie dit qu’on ne l’écoute pas. Le Brésil a-t-il un chef ou trois fuseaux horaires ?","answers":[{"tone":"franche","label":"Il a un chef qui doit écouter trois fois plus. Je me rendrai dans chaque région, et j’accepterai de m’y faire gronder en direct.","effects":{"cohesion":4,"popularite":2,"budget":-3},"delayed":[{"delay":2,"effects":{"economie":-1},"label":"Le planning de la tournée dépasse les budgets"}],"news":"Le président annonce une tournée dans chaque région du pays"},{"tone":"langue-de-bois","label":"Le Brésil est un et divers à la fois. Cette richesse fédérative est notre force, à condition de la cultiver avec patience et pédagogie.","effects":{"cohesion":2,"international":-2},"news":"Fédération : le Planalto vante l’unité dans la diversité"},{"tone":"offensive","label":"Ceux qui comptent les réais d’une région contre l’autre font le jeu des diviseurs. Je ne plaiderai pas pour les chiffres de clocher.","effects":{"popularite":3,"cohesion":-4,"assemblee":-2,"economie":2},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Des gouverneurs boudent la prochaine réunion"}],"news":"Le président rejette la « guerre des régions »"}]},{"id":"bresil-q-amazonie-chiffres","theme":"ecologie","condition":{"gauge":"ecologie","op":"<","value":55},"text":"Les satellites comptent les arbres abattus, et les chiffres ne vous aiment pas. L’Amazonie reste-t-elle le poumon du monde, ou un poumon sous assistance respiratoire ?","answers":[{"tone":"franche","label":"Elle respire encore, mais mal. Les amendes doivent être payées, les satellites écoutés, et les entreprises de bois illégales doivent fermer.","effects":{"ecologie":5,"economie":-3},"delayed":[{"delay":3,"effects":{"international":2},"label":"Les partenaires étrangers saluent le virage"}],"news":"Amazonie : « amendes payées, scieries fermées », annonce le président"},{"tone":"langue-de-bois","label":"L’Amazonie est un patrimoine mondial qui reste d’abord une responsabilité brésilienne. Nous alignons conservation et développement durable.","effects":{"ecologie":2,"economie":-2},"news":"Amazonie : conservation et développement « alignés », dit-on"},{"tone":"offensive","label":"L’Amazonie est brésilienne, et les leçons de forêt venues de pays qui ont rasé la leur depuis longtemps sont reçues avec politesse, pas avec docilité.","effects":{"popularite":4,"ecologie":-3,"international":-4},"delayed":[{"delay":2,"effects":{"ecologie":-2,"international":-1},"label":"Un fonds étranger suspend sa contribution"}],"news":"Le président répond aux « leçons de forêt » venues de l’étranger"}]},{"id":"bresil-q-mercosul-accord","theme":"international","condition":{"gauge":"international","op":"<","value":50},"text":"Le Mercosul rêve d’un accord avec l’autre rive de l’Atlantique depuis qu’on y négocie en rond. Votre diplomatie est-elle patiente, ou simplement très lente ?","answers":[{"tone":"franche","label":"Elle est lente, et je le regrette. Un accord doit protéger nos exportations sans sacrifier la forêt, et ce deuxième point retarde le premier.","effects":{"international":4,"economie":-2},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les exportateurs se préparent à de nouveaux quotas"}],"news":"Mercosul : le président admet un accord lent mais exigeant"},{"tone":"langue-de-bois","label":"Le Brésil joue un rôle de pont entre les blocs. Nous continuons d’échanger avec toutes les parties dans un esprit d’ouverture et de pragmatisme.","effects":{"international":2,"popularite":-2},"news":"Diplomatie : « un pont entre les blocs », dit le Planalto"},{"tone":"offensive","label":"Nous n’avons de leçons à recevoir de personne sur le commerce. Qui veut notre soja et notre énergie propre sait où nous trouver, sans conditions.","effects":{"economie":3,"popularite":3,"international":-5},"delayed":[{"delay":3,"effects":{"international":-2,"economie":-1},"label":"Des délégations annulent leur visite à Brasilia"}],"news":"Commerce : le président refuse « toute leçon » de ses partenaires"}]},{"id":"bresil-q-coalition-jeudi","theme":"assemblee","condition":{"gauge":"assemblee","op":"<","value":35},"text":"Au Congrès, l’Union du Centre Large vote avec qui paie le mieux, les Socialistes du Peuple tiennent des conférences, les Libéraux comptent leurs sièges. Qui est, ce matin, votre majorité ?","answers":[{"tone":"franche","label":"Aucune majorité stable. Je gouverne par accords successifs, projet après projet, et je préfère l’avouer plutôt que de la décorer.","effects":{"assemblee":4,"popularite":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Le centre réclame de nouveaux ministères"}],"news":"Congrès : le président reconnaît gouverner « projet après projet »"},{"tone":"langue-de-bois","label":"Ma majorité, c’est celle des Brésiliens, qui s’exprime à travers un Congrès pluriel. Le dialogue est permanent et la porte est toujours ouverte.","effects":{"assemblee":2,"popularite":-2},"news":"« La porte est ouverte » : le président sans majorité nette"},{"tone":"offensive","label":"Ma majorité, c’est celle qui vote les lois, et celle qui ne les vote pas apprendra ce que vaut le silence d’un ministère. Je compte les voix, pas les chaises.","effects":{"assemblee":5,"popularite":-3,"cohesion":-2},"delayed":[{"delay":3,"effects":{"assemblee":-4},"label":"Le centre retourne sa veste, encore une fois"}],"news":"Le président menace le Congrès de « silence ministériel »"}]},{"id":"bresil-q-soja-record","theme":"economie","condition":{"gauge":"economie","op":">","value":60},"text":"Les récoltes de soja et de viande battent des records, les ports débordent, les camions aussi. Le Brésil est-il en train de devenir une ferme géante avec un drapeau ?","answers":[{"tone":"franche","label":"Une ferme qui nourrit une bonne partie de la planète, c’est un honneur. Mais je veux que la valeur reste ici : industrie, transformation, emplois.","effects":{"economie":3,"popularite":3,"ecologie":-2},"delayed":[{"delay":4,"effects":{"economie":2},"label":"Une usine de transformation ouvre ses portes"}],"news":"Soja record : le président veut transformer plus sur place"},{"tone":"langue-de-bois","label":"L’agro-industrie est un moteur essentiel de notre compétitivité. Nous accompagnerons la filière avec innovation et durabilité.","effects":{"economie":2,"ecologie":-2},"news":"Agro-industrie : le Planalto promet « innovation et durabilité »"},{"tone":"offensive","label":"Qu’on me cite un pays qui se plaint d’avoir trop de richesses naturelles. Laissons les petits donneurs de leçons compter leurs ananas.","effects":{"economie":5,"popularite":2,"international":-3,"ecologie":-3},"delayed":[{"delay":2,"effects":{"ecologie":-2},"label":"Le front pionnier avance un peu plus vite"}],"news":"Le président se moque de ceux qui s’inquiètent du soja"}]},{"id":"bresil-q-popularite-haute","theme":"popularite","condition":{"gauge":"popularite","op":">","value":65},"text":"Votre cote est excellente, les rues vous sourient et les photographes aussi. Qui, dans votre entourage, ose encore vous dire que vous vous trompez ?","answers":[{"tone":"franche","label":"Ma grand-mère le disait avec art, et j’en ai gardé la leçon : un chef qui n’est plus contredit est déjà en retard d’une erreur.","effects":{"popularite":3,"assemblee":2,"economie":-2},"news":"Cote record : « Ma grand-mère me contredisait », confie le président"},{"tone":"langue-de-bois","label":"Les sondages sont un baromètre, jamais une boussole. Je reste concentré sur la méthode, humble face à l’ampleur de la tâche.","effects":{"popularite":2,"cohesion":-2},"news":"Sondages : « un baromètre, pas une boussole », selon le président"},{"tone":"offensive","label":"Personne ne se trompe quand les Brésiliens sont d’accord avec nous. Ceux qui doutent n’ont qu’à regarder les chiffres, ou changer de lunettes.","effects":{"popularite":5,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"L’excès de confiance fait sourire les éditorialistes"}],"news":"Le président balaie les critiques : « Changez de lunettes »"}]},{"id":"bresil-q-hydraulique-surplus","theme":"ecologie","condition":{"gauge":"ecologie","op":">","value":70},"text":"L’énergie hydraulique alimente l’essentiel du réseau, et le pays se vante de rouler propre. Mais les grands barrages ont déplacé des rivières et des villages. À quel prix ?","answers":[{"tone":"franche","label":"Au prix de choix que nous aurions dû mieux discuter avec ceux qui vivaient là. Désormais, aucun grand ouvrage sans consultation réelle.","effects":{"ecologie":3,"cohesion":3,"economie":-3},"delayed":[{"delay":3,"effects":{"economie":-1},"label":"Des chantiers sont retardés d’un an"}],"news":"Barrages : le président promet une consultation avant chantier"},{"tone":"langue-de-bois","label":"L’hydraulique est un atout stratégique. Nous poursuivons un mix énergétique équilibré, dans le respect des territoires et des communautés.","effects":{"ecologie":2,"cohesion":-2},"news":"Énergie : « mix équilibré » et respect des territoires, promis"},{"tone":"offensive","label":"Un pays qui produit de l’énergie propre à ce niveau devrait recevoir des compliments, pas des questions. Les critiques peuvent éteindre leurs lampes en rentrant.","effects":{"popularite":4,"international":2,"cohesion":-4},"delayed":[{"delay":2,"effects":{"cohesion":-2,"ecologie":-1},"label":"Des communautés riveraines se disent humiliées"}],"news":"Le président : « Les critiques peuvent éteindre leurs lampes »"}]},{"id":"bresil-q-budget-excedent","theme":"budget","condition":{"gauge":"budget","op":">","value":60},"text":"Vos comptes sont sains, ce qui est rare, et chacun voit déjà une dépense à faire. Les gouverneurs, les ministres et les parlementaires font la queue. Qui sert-on en premier ?","answers":[{"tone":"franche","label":"Personne en premier. Un tiers à la dette, un tiers aux écoles et aux hôpitaux, un tiers à un fonds de réserve que même moi ne pourrai pas ouvrir.","effects":{"budget":3,"popularite":2,"assemblee":-3},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Les parlementaires rêvent d’un tournevis pour le coffre"}],"news":"Excédent : le président partage en trois et ferme le coffre"},{"tone":"langue-de-bois","label":"La rigueur n’est pas une fin en soi. Nous arbitrerons entre les priorités avec discernement, dans l’intérêt supérieur de la nation.","effects":{"budget":2,"assemblee":-2},"news":"Excédent : « arbitrer avec discernement », annonce le Planalto"},{"tone":"offensive","label":"L’argent public n’est pas un gâteau d’anniversaire pour les élus qui soufflent les bougies. Il va aux Brésiliens qui paient, pas à ceux qui réclament.","effects":{"budget":4,"popularite":3,"assemblee":-4,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Le Congrès retarde le vote d’un projet clé"}],"news":"Le président ferme la caisse aux élus : « Pas de gâteau »"}]},{"id":"bresil-q-pouvoir-achat-haut","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":">","value":60},"text":"Les Brésiliens mangent mieux, achètent un peu plus et commencent à voyager. Craignez-vous que la prospérité ne donne aux plus riches l’idée de réclamer des baisses d’impôts ?","answers":[{"tone":"franche","label":"Ils le réclameront, c’est certain. Mais la consommation doit durer, et un pays qui s’enrichit doit d’abord fermer ses écarts, pas ses caisses.","effects":{"pouvoirAchat":3,"cohesion":2,"economie":-3},"delayed":[{"delay":3,"effects":{"budget":2},"label":"Les recettes confirment la prudence"}],"news":"Prospérité : le président refuse de baisser les impôts des riches"},{"tone":"langue-de-bois","label":"Chaque Brésilien doit pouvoir profiter des fruits de la croissance. Nous suivrons la situation avec attention et réalisme.","effects":{"pouvoirAchat":2,"economie":-2},"news":"Croissance : « suivre avec attention », répond le Planalto"},{"tone":"offensive","label":"La seule liste que je reçois en ce moment est celle des gens qui veulent plus de cadeaux. Elle est longue, et elle reste dans le tiroir.","effects":{"pouvoirAchat":3,"popularite":3,"economie":-4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Des investisseurs reportent leurs projets"}],"news":"Le président range la liste des demandes fiscales dans un tiroir"}]},{"id":"bresil-q-securite-routes","theme":"securite","text":"Avec la longueur des routes, un camion peut mettre trois jours à traverser un seul État. Les accidents s’accumulent sur les mêmes tronçons. Le Brésil roule-t-il trop vite ou trop loin ?","answers":[{"tone":"franche","label":"Trop loin, avec trop de camions et trop peu de rails. Je veux déplacer une partie du fret sur le train, et réparer les tronçons les plus meurtriers d’abord.","effects":{"securite":3,"budget":-3,"economie":2},"delayed":[{"delay":4,"effects":{"economie":2},"label":"Le premier corridor ferroviaire ouvre"}],"news":"Routes : le président veut mettre le fret sur les rails"},{"tone":"langue-de-bois","label":"La mobilité est un enjeu transversal. Un schéma directeur multimodal sera élaboré en concertation avec les États et les opérateurs.","effects":{"securite":2,"popularite":-2},"news":"Routes : un « schéma directeur multimodal » est annoncé"},{"tone":"offensive","label":"Ceux qui critiquent le camion n’ont jamais vu un champ de soja attendre un train. Le camion nourrit le pays, et il continuera de rouler.","effects":{"popularite":3,"economie":2,"securite":-4,"ecologie":-3},"delayed":[{"delay":3,"effects":{"securite":-2},"label":"Un grave accident relance le débat"}],"news":"Le président défend le camion : « Il nourrit le pays »"}]},{"id":"bresil-q-education-temps-plein","theme":"cohesion","text":"Les écoles à temps plein promettent des enfants nourris, occupés et un peu plus instruits. Qui va payer les repas, les cuisiniers et le goûter dans un pays de cette taille ?","answers":[{"tone":"franche","label":"L’État fédéral, les États, les communes, chacun une part, et un tableau public de ce que chacun a vraiment versé. Les écoles sauront qui a oublié.","effects":{"cohesion":4,"budget":-3},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les cantines du Nord-Est ouvrent en premier"}],"news":"École à temps plein : le président publie le tableau des paiements"},{"tone":"langue-de-bois","label":"L’éducation est l’avenir. Nous travaillons à un modèle de financement partagé, durable et ambitieux avec tous les niveaux de gouvernement.","effects":{"cohesion":2,"assemblee":-2},"news":"École : un « modèle de financement partagé » est annoncé"},{"tone":"offensive","label":"Que les gouverneurs qui trouvent de l’argent pour des stades en trouvent aussi pour des cantines. On verra vite qui aime vraiment les enfants.","effects":{"cohesion":3,"popularite":3,"assemblee":-3,"international":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Plusieurs gouverneurs boycottent la réunion suivante"}],"news":"Le président aux gouverneurs : « Des cantines, pas que des stades »"}]},{"id":"bresil-q-sante-sus","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":50},"text":"Le système de santé universel soigne des millions de gens gratuitement, mais les files s’allongent dans les postes. Peut-on soigner à la brésilienne, c’est-à-dire avec patience ?","answers":[{"tone":"franche","label":"La patience ne soigne personne. Je veux des files publiques, des rendez-vous donnés par application, et des médecins formés là où ils manquent.","effects":{"pouvoirAchat":3,"budget":-3},"delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les premiers rendez-vous en ligne rassurent"}],"news":"Santé : le président veut des files publiques et des rendez-vous en ligne"},{"tone":"langue-de-bois","label":"Notre système est un modèle admiré. Nous le renforcerons avec des investissements ciblés et une gouvernance modernisée.","effects":{"pouvoirAchat":2,"popularite":-2},"news":"Santé : le Planalto promet « investissements ciblés »"},{"tone":"offensive","label":"Ceux qui parlent de privatiser la santé n’ont jamais attendu à six heures du matin devant un poste. Ils feraient bien d’y passer une nuit.","effects":{"popularite":4,"pouvoirAchat":2,"economie":-3,"assemblee":-3},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Le bloc libéral du Congrès réplique par une motion"}],"news":"Le président défie les partisans de la privatisation de la santé"}]},{"id":"bresil-q-cohesion-haute","theme":"cohesion","condition":{"gauge":"cohesion","op":">","value":62},"text":"Le pays se parle enfin : les régions s’écoutent, les écoles de samba défilent ensemble. Qu’allez-vous gâcher en premier pour retrouver vos habitudes ?","answers":[{"tone":"franche","label":"Rien, si on me laisse faire, mais je connais ma réputation. Surveillez-moi surtout quand je parle d’impôts après minuit.","effects":{"cohesion":3,"popularite":3,"budget":-2},"news":"Le président promet de ne rien gâcher, sauf après minuit"},{"tone":"langue-de-bois","label":"L’unité nationale est un bien précieux qu’il faut entretenir au quotidien, avec humilité et un souci constant du dialogue.","effects":{"cohesion":2,"popularite":-2},"news":"Unité nationale : un « bien précieux », rappelle le Planalto"},{"tone":"offensive","label":"L’unité ne se gâche pas, elle s’entraîne. Ceux qui rêvent de division devront trouver une autre salle de sport.","effects":{"cohesion":3,"popularite":3,"assemblee":-3,"international":-2},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"L’opposition accuse le président d’ironie déplacée"}],"news":"Le président : « L’unité s’entraîne, la division va au sport ailleurs »"}]},{"id":"bresil-q-cop-sommet","theme":"international","condition":{"gauge":"international","op":">","value":65},"text":"Le pays accueille un grand sommet mondial sur le climat dans une ville amazonienne. Les délégués s’inquiètent de la chaleur, des moustiques et du Wi-Fi. Que leur répondez-vous ?","answers":[{"tone":"franche","label":"Qu’ils viennent voir la forêt de près. Si la chaleur les dérange, ils comprendront mieux pourquoi nous leur demandons d’agir.","effects":{"international":4,"ecologie":2,"budget":-3},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"Les ventilateurs d’hôtel font la une"}],"news":"Sommet climat : « Venez voir la forêt de près », lance le président"},{"tone":"langue-de-bois","label":"Nous accueillerons toutes les délégations avec hospitalité. Les enjeux logistiques seront traités avec sérieux, comme les enjeux climatiques.","effects":{"international":2,"budget":-2},"news":"Sommet : l’hospitalité brésilienne promise aux délégations"},{"tone":"offensive","label":"Un pays qui accueille un sommet dans la forêt n’a pas à justifier la climatisation. Ceux qui veulent un hôtel cinq étoiles n’ont qu’à rester chez eux.","effects":{"popularite":4,"ecologie":2,"international":-4},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Deux ministres étrangers annulent leur venue"}],"news":"Le président aux délégués : « Restez chez vous si le moustique vous gêne »"}]},{"id":"bresil-q-crise-incendies","theme":"crise","crisisId":"bresil-incendies-amazonie","text":"La fumée des incendies d’Amazonie atteint des villes situées à des milliers de kilomètres. Les enfants toussent, les compagnies aériennes s’agacent. Quand éteint-on le feu ?","answers":[{"tone":"franche","label":"Dès que nous avons les avions, les brigades et la volonté. J’ai ordonné la mobilisation, et je veux un rapport hebdomadaire public.","effects":{"ecologie":4,"budget":-3,"economie":-2},"delayed":[{"delay":2,"effects":{"ecologie":2,"international":1},"label":"La fumée recule au-dessus du Centre-Ouest"}],"news":"Incendies : le président mobilise avions et brigades"},{"tone":"langue-de-bois","label":"Nous suivons la situation heure par heure avec les États concernés. Toutes les ressources nécessaires seront mobilisées au moment opportun.","effects":{"ecologie":2,"popularite":-2},"news":"Incendies : le Planalto suit l’affaire « heure par heure »"},{"tone":"offensive","label":"Les incendies sont aussi instrumentalisés par ceux qui rêvent d’un Brésil sous cloche. Nous éteindrons les feux, pas les ambitions du pays.","effects":{"popularite":3,"ecologie":-3,"international":-4},"delayed":[{"delay":2,"effects":{"international":-2,"ecologie":-1},"label":"Des capitales étrangères convoquent l’ambassadeur"}],"news":"Incendies : le président dénonce une « instrumentalisation »"}]},{"id":"bresil-q-crise-boycott","theme":"crise","crisisId":"bresil-sanctions-commerciales-forets","text":"Des acheteurs étrangers menacent de refuser le soja et le bœuf dont l’origine n’est pas traçable. Les exportateurs tremblent, les ports aussi. Traçable, vraiment ?","answers":[{"tone":"franche","label":"Pas encore partout, et c’est le problème. Je lance un registre numérique obligatoire : qui ne peut pas prouver l’origine ne vend pas.","effects":{"international":4,"ecologie":3,"economie":-4},"delayed":[{"delay":3,"effects":{"economie":2,"international":1},"label":"Les premiers lots certifiés partent vers l’Europe"}],"news":"Boycott : le président impose un registre d’origine obligatoire"},{"tone":"langue-de-bois","label":"Nos filières disposent de systèmes robustes de qualité et de durabilité. Le dialogue avec nos partenaires commerciaux est constant et constructif.","effects":{"international":2,"economie":-2},"news":"Boycott : le Planalto vante des « systèmes robustes »"},{"tone":"offensive","label":"Ce boycott est un protectionnisme déguisé. Si nos produits déplaisent, d’autres marchés ont plus d’appétit et moins de leçons à donner.","effects":{"economie":3,"popularite":3,"international":-5},"delayed":[{"delay":3,"effects":{"economie":-2,"international":-2},"label":"Les contrats alternatifs tardent à arriver"}],"news":"Boycott : le président cherche d’autres clients et claque la porte"}]},{"id":"bresil-q-crise-carnaval","theme":"crise","crisisId":"bresil-carnaval-depenses","text":"Le carnaval a dépassé ses budgets de sécurité, de nettoyage et d’ambulances. Les écoles de samba défilent, les comptes ne défilent pas. Qui paie la fête ?","answers":[{"tone":"franche","label":"Les villes, les États et l’État fédéral, avec un contrôle public de chaque dépense. La fête est belle, la facture doit l’être aussi.","effects":{"budget":3,"cohesion":2,"popularite":-3},"delayed":[{"delay":3,"effects":{"budget":2},"label":"Les écoles de samba publient enfin leurs comptes"}],"news":"Carnaval : le président veut une facture « aussi belle que la fête »"},{"tone":"langue-de-bois","label":"Le carnaval est un patrimoine vivant qui mérite un soutien équilibré. Une concertation sera ouverte avec tous les acteurs de la chaîne festive.","effects":{"popularite":2,"budget":-2},"news":"Carnaval : concertation promise avec « la chaîne festive »"},{"tone":"offensive","label":"Qui compte les paillettes n’a jamais vu une favela se mettre en scène. Le carnaval rapporte au pays bien plus qu’il ne coûte, et je n’en démords pas.","effects":{"popularite":5,"cohesion":2,"budget":-4,"economie":-2},"delayed":[{"delay":2,"effects":{"budget":-2},"label":"La Cour des comptes demande des explications"}],"news":"Carnaval : « Les paillettes rapportent », défend le président"}]},{"id":"bresil-q-crise-inflation","theme":"crise","crisisId":"bresil-inflation-aliments","text":"Le prix du riz, du haricot et du café grimpe plus vite que les rythmes de samba. Un ménage sur deux vous dit que le panier est devenu un luxe. Ce sont des chiffres ou une plainte ?","answers":[{"tone":"franche","label":"Les deux, et la plainte est mieux informée que les chiffres. Je baisse les taxes sur le panier de base, et j’en assume le trou.","effects":{"pouvoirAchat":5,"budget":-4},"delayed":[{"delay":3,"effects":{"budget":-2,"economie":1},"label":"Le déficit se fait sentir dans les caisses"}],"news":"Flambée des prix : le président baisse les taxes du panier de base"},{"tone":"langue-de-bois","label":"L’inflation alimentaire a des causes multiples, conjoncturelles comme structurelles. Nous sommes mobilisés à tous les niveaux.","effects":{"pouvoirAchat":2,"popularite":-3},"news":"Inflation : le Planalto se dit « mobilisé à tous les niveaux »"},{"tone":"offensive","label":"Quand les prix montent, certains font des fortunes. Je leur dis ceci : un contrôle des marges, un export freiné en cas de pénurie, et un peu de décence.","effects":{"pouvoirAchat":4,"popularite":3,"economie":-4,"international":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les exportateurs menacent de se tourner vers d’autres marchés"}],"news":"Prix alimentaires : le président freine les exports et contrôle les marges"}]},{"id":"bresil-q-crise-secheresse","theme":"crise","crisisId":"bresil-secheresse-nordeste","text":"Les réservoirs du Nord-Est sont vides, le bétail maigrit, et les camions-citernes remplacent les rivières. On promet de l’eau depuis des décennies. Où est-elle ?","answers":[{"tone":"franche","label":"Dans des projets inachevés que je vais terminer, et dans des citernes que j’envoie dès demain. Je rendrai compte de chaque kilomètre de canal.","effects":{"cohesion":4,"popularite":2,"budget":-4},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les premières communes raccordées remercient"}],"news":"Sécheresse : citernes dès demain, canaux achevés, promet le président"},{"tone":"langue-de-bois","label":"La gestion de l’eau est un défi structurant. Des solutions durables seront identifiées en lien avec les communautés et les gouvernements locaux.","effects":{"cohesion":2,"popularite":-3},"news":"Sécheresse : « solutions durables » à identifier, dit-on"},{"tone":"offensive","label":"Les grands propriétaires qui détournent les puits au détriment des villages devront rendre leur eau, ou leur terre. Je ne laisse pas un village mourir de soif par politesse.","effects":{"cohesion":3,"popularite":4,"economie":-3,"assemblee":-3},"delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Les parlementaires ruraux haussent le ton"}],"news":"Sécheresse : le président menace les détourneurs de puits"}]},{"id":"bresil-q-crise-camionneurs","theme":"crise","crisisId":"bresil-greve-camionneurs","text":"Les camionneurs bloquent les routes pour protester contre le prix du diesel, les péages et la fatigue. Les supermarchés se vident, les files grossissent. Qui cédera en premier ?","answers":[{"tone":"franche","label":"Ceux qui bloquent ont raison sur la fatigue et tort sur le blocage. Je négocie le diesel et les péages, mais la route doit rouvrir ce soir.","effects":{"securite":3,"economie":2,"budget":-3,"popularite":-2},"delayed":[{"delay":2,"effects":{"economie":2},"label":"Les camions reprennent leur route"}],"news":"Grève des camionneurs : négociation, mais « la route rouvre ce soir »"},{"tone":"langue-de-bois","label":"Le dialogue social est la voie. Nous recevons les représentants du secteur avec respect pour trouver des solutions équilibrées.","effects":{"economie":2,"securite":-2},"news":"Camionneurs : le Planalto reçoit les représentants « avec respect »"},{"tone":"offensive","label":"Une grève qui affame un pays n’est plus une grève, c’est un chantage. Les barrages seront levés par les forces de l’ordre, sans exception.","effects":{"securite":4,"popularite":2,"cohesion":-4,"economie":-2},"delayed":[{"delay":3,"effects":{"cohesion":-2,"economie":-2},"label":"Des convois de colère annoncés pour la semaine prochaine"}],"news":"Camionneurs : le président ordonne de lever les barrages"}]},{"id":"bresil-q-crise-indigenes","theme":"crise","crisisId":"bresil-peuples-indigenes-terres","text":"Des peuples autochtones réclament la démarcation de leurs terres, des exploitants réclament le contraire, et chacun a des cartes. Vous tracez la frontière où, exactement ?","answers":[{"tone":"franche","label":"Là où le droit le dit, avec des cartes publiques, des recours possibles, et un calendrier. Les terres reconnues seront protégées, sans exception.","effects":{"cohesion":2,"ecologie":4,"economie":-3,"assemblee":-3},"delayed":[{"delay":3,"effects":{"international":2},"label":"Les organisations internationales saluent la méthode"}],"news":"Terres indigènes : le président annonce cartes publiques et calendrier"},{"tone":"langue-de-bois","label":"Chaque situation est singulière. Nous travaillons à une solution équilibrée dans le respect de toutes les sensibilités et des procédures.","effects":{"cohesion":2,"ecologie":-2},"news":"Terres indigènes : « une solution équilibrée » est à l’étude"},{"tone":"offensive","label":"Le Brésil n’appartiendra ni aux cartes de vieux dossiers ni aux slogans de bureau. Les terres seront tracées vite, quitte à froisser quelques lobbies.","effects":{"ecologie":4,"popularite":2,"economie":-3,"assemblee":-4},"delayed":[{"delay":2,"effects":{"assemblee":-3,"cohesion":-1},"label":"Le caucus agricole boycotte une séance"}],"news":"Terres indigènes : le président accélère, le lobby rural grince"}]},{"id":"bresil-q-crise-generique","theme":"crise","text":"Trois ministres se contredisent dans la même matinée, et vous revenez d’un voyage. Est-ce une crise, une coïncidence, ou simplement une journée normale à Brasilia ?","answers":[{"tone":"franche","label":"Une journée normale, ce qui est le problème. Je réunirai le gouvernement et nous parlerons d’une seule voix, ou nous changerons de voix.","effects":{"assemblee":3,"popularite":2,"cohesion":-2},"news":"Trois ministres, trois versions : le président rappelle l’équipe à l’ordre"},{"tone":"langue-de-bois","label":"Il n’y a pas de contradiction, seulement des nuances qui enrichissent le débat démocratique au sein de l’exécutif.","effects":{"assemblee":2,"popularite":-3},"news":"Ministres divisés : « des nuances qui enrichissent le débat »"},{"tone":"offensive","label":"Le seul qui m’a contredit ce matin, c’est le réveil. Les autres liront les consignes ou iront occuper leur temps ailleurs.","effects":{"popularite":4,"assemblee":-3,"cohesion":-3},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Deux ministres envisagent de partir"}],"news":"Le président recadre ses ministres : « Seul le réveil m’a contredit »"}]},{"id":"bresil-q-scandale-chauffeur","theme":"scandale","text":"Un journal révèle que le cousin d’un ministre a obtenu un contrat de fournitures pour les cantines… de trois États dont il n’a jamais vu une école. Votre réaction ?","answers":[{"tone":"franche","label":"Le contrat est suspendu, le ministre s’explique devant la commission et, si c’est un abus, il part. Les cantines ne sont pas une affaire de famille.","effects":{"popularite":3,"cohesion":2,"assemblee":-3},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Le ministre sème des rumeurs de rancœur"}],"news":"Contrat des cantines : le président suspend tout, le ministre s’explique"},{"tone":"langue-de-bois","label":"Une enquête est en cours et il serait déplacé de commenter. Je fais confiance aux institutions de contrôle et à la présomption d’innocence.","effects":{"assemblee":2,"popularite":-3},"news":"Scandale des cantines : « une enquête est en cours », répète le Planalto"},{"tone":"offensive","label":"Je reconnais là la routine de certains titres : un cousin, un contrat, une coïncidence suspecte. Mon gouvernement a des défauts, pas ceux qu’on lui prête.","effects":{"assemblee":3,"popularite":2,"international":-2,"cohesion":-4},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"De nouvelles factures sortent dans la presse"}],"news":"Le président attaque la presse : « Un cousin, un contrat, un titre »"}]},{"id":"bresil-q-scandale-fuite","theme":"scandale","text":"Des messages privés du palais circulent sur les réseaux : on y voit vos conseillers se moquer des gouverneurs, du Congrès et d’un célèbre chanteur de pagode. Vous avez un commentaire ?","answers":[{"tone":"franche","label":"Mes conseillers ont l’esprit mal tourné, et moi aussi parfois. Je présente mes excuses aux gouverneurs, au Congrès et au chanteur, qui chante mieux que nous gouvernons.","effects":{"popularite":4,"cohesion":2,"assemblee":-2},"news":"Messages fuités : le président s’excuse, le chanteur a le dernier mot"},{"tone":"langue-de-bois","label":"Des échanges privés sortent de leur contexte. Cette affaire n’est pas à la hauteur des défis du pays, et je n’en dirai pas davantage.","effects":{"assemblee":2,"popularite":-2},"news":"Fuite des messages : « hors contexte », réplique le Planalto"},{"tone":"offensive","label":"Le véritable scandale n’est pas ce qu’on dit en privé, mais qui vole les messages. Une enquête sur la fuite sera ouverte, et les curieux de pièces jointes seront identifiés.","effects":{"popularite":3,"assemblee":2,"cohesion":-3,"international":-3},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"L’enquête tourne court, et fuite elle aussi"}],"news":"Messages fuités : le président ouvre une enquête sur les fuiteurs"}]},{"id":"bresil-q-scandale-jet","theme":"scandale","text":"Un haut fonctionnaire a utilisé un avion officiel pour assister à une finale de championnat de football, avec une famille nombreuse et une valise de maillots. Excuses ou statistiques ?","answers":[{"tone":"franche","label":"Ni l’un ni l’autre : il rembourse chaque siège et chaque maillot. Un fonctionnaire n’a pas à voyager avec les fonds publics pour une finale, même une belle.","effects":{"popularite":4,"budget":2,"assemblee":-3},"news":"Avion officiel : le fonctionnaire rembourse chaque siège et chaque maillot"},{"tone":"langue-de-bois","label":"Le déplacement s’inscrivait dans un cadre protocolaire. Les règles seront examinées afin d’éviter toute ambiguïté à l’avenir.","effects":{"assemblee":2,"popularite":-2},"news":"Avion officiel : un « cadre protocolaire » invoqué pour la finale"},{"tone":"offensive","label":"On pardonne ici tous les excès pour le football, sauf à ceux qui ont gagné. Que ceux qui n’ont jamais volé un but nous jettent la première pierre.","effects":{"popularite":4,"cohesion":-3,"international":-2,"budget":-2},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Les chroniqueurs sortent la calculette des kilomètres"}],"news":"Le président défend l’escapade footballistique du fonctionnaire"}]},{"id":"bresil-q-culture-selecao","theme":"popularite","text":"La sélection nationale joue demain soir, et votre agenda est étrangement vide. Annulez-vous le conseil des ministres pour regarder le match, ou le déplacez-vous sur grand écran ?","answers":[{"tone":"franche","label":"Je le déplace sur grand écran, et je parie sur la sélection. Un pays qui gagne a de meilleures chances de voter son budget.","effects":{"popularite":4,"budget":-2},"news":"Match de la sélection : le conseil des ministres passe sur grand écran"},{"tone":"langue-de-bois","label":"Le sport fédère, et mon agenda s’adaptera aux exigences de la vie nationale tout en garantissant la continuité du service de l’État.","effects":{"popularite":2,"economie":-2},"news":"Football : l’agenda présidentiel « s’adaptera aux exigences »"},{"tone":"offensive","label":"On gouverne aussi bien devant un écran que derrière un bureau, et l’opposition le sait : elle ne regarde jamais les matchs, elle les commente.","effects":{"popularite":5,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":1,"effects":{"popularite":-2},"label":"La sélection perd, la facture est pour le palais"}],"news":"Le président assume le match : « On gouverne aussi devant un écran »"}]},{"id":"bresil-q-culture-feijoada","theme":"cohesion","text":"Un reportage vous demande le plat qui représente le mieux le Brésil. La feijoada, le churrasco, l’acarajé, le pão de queijo ? Chaque région surveille votre réponse comme un penalty.","answers":[{"tone":"franche","label":"La feijoada, et je suis prêt à en discuter longuement avec les régions fâchées. À chacune ensuite son plat, sa fête et son moment de gloire à la télévision.","effects":{"cohesion":3,"popularite":2,"budget":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les partisans de l’acarajé crient au complot"}],"news":"Plat national : le président choisit la feijoada et promet une fête à chaque région"},{"tone":"langue-de-bois","label":"Chaque région contribue à une gastronomie plurielle. Choisir un plat serait réducteur, et le Brésil se goûte dans sa diversité.","effects":{"cohesion":2,"popularite":-2},"news":"Gastronomie : le Planalto refuse de choisir un plat national"},{"tone":"offensive","label":"Un pays qui hésite entre quatre plats est un pays qui a de la chance. Que ceux qui n’ont pas de dessert se taisent et nous envient.","effects":{"popularite":3,"cohesion":-3,"international":-2,"economie":2},"news":"Le président sur la gastronomie : « Le reste du monde n’a que le dessert »"}]},{"id":"bresil-q-culture-fuseaux","theme":"cohesion","text":"Le pays s’étend sur plusieurs fuseaux horaires, et les journaux télévisés prennent un quart d’heure de retard à chaque frontière. Faut-il unifier l’heure, ou simplement accepter que Brasilia vive à son rythme ?","answers":[{"tone":"franche","label":"Je ne toucherai pas à l’heure : chacun son soleil. Mais les réunions fédérales commenceront à l’heure du plus petit fuseau, pour que personne ne dorme en décalé.","effects":{"cohesion":3,"economie":-2},"news":"Fuseaux horaires : le président garde l’heure, déplace les réunions"},{"tone":"langue-de-bois","label":"La question de l’heure appelle une réflexion approfondie, associant les États, les secteurs économiques et les citoyens.","effects":{"cohesion":2,"popularite":-2},"news":"Fuseaux horaires : une « réflexion approfondie » est lancée"},{"tone":"offensive","label":"Une heure unique, et que ceux qui se plaignent de se lever tôt préviennent le soleil. Le pays gagnera des millions d’heures de productivité.","effects":{"economie":4,"popularite":2,"cohesion":-4,"international":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2,"popularite":-2},"label":"Les États de l’Ouest refusent de changer leur montre"}],"news":"Heure unique : le président promet « des millions d’heures de productivité »"}]},{"id":"bresil-q-culture-festa-junina","theme":"popularite","text":"Pour la fête de la Saint-Jean, le Nord-Est vous invite à danser la quadrille, manger du maïs et supporter un feu d’artifice qui ressemble à une inspection des douanes. Vous venez ?","answers":[{"tone":"franche","label":"Je viens, je danse mal, et j’ai prévenu qu’on rira de moi. Un président qui ne danse pas la quadrille ne mérite pas le maïs.","effects":{"popularite":4,"cohesion":2,"economie":-2},"news":"Fête de la Saint-Jean : le président annonce qu’il dansera, mal"},{"tone":"langue-de-bois","label":"Cette fête incarne des traditions populaires qu’il convient de préserver. Je serai représenté à la hauteur de l’enjeu culturel.","effects":{"popularite":2,"cohesion":-2},"news":"Saint-Jean : le président « représenté à la hauteur de l’enjeu »"},{"tone":"offensive","label":"Une fête de village qui impose un feu d’artifice de douane à ses invités mérite d’être réformée. Je viendrai, mais avec des bouchons d’oreilles et un programme.","effects":{"popularite":3,"cohesion":-3,"budget":-2,"international":2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les groupes de danse boycottent l’invitation"}],"news":"Fête de la Saint-Jean : le président réclame des bouchons d’oreilles"}]},{"id":"bresil-q-culture-voisins","theme":"international","text":"Vos voisins hispanophones disent que le Brésil les regarde de haut parce qu’il parle portugais et possède une plus grande forêt. Faut-il leur envoyer un dictionnaire ou une invitation ?","answers":[{"tone":"franche","label":"Une invitation, avec une carte bilingue. La langue sépare moins que les routes et les douanes, et je commencerai par les secondes.","effects":{"international":4,"economie":2,"budget":-3},"news":"Voisins : le président invite et promet des routes bilingues"},{"tone":"langue-de-bois","label":"Le Brésil entretient avec ses voisins des liens fraternels fondés sur le respect mutuel et la coopération régionale.","effects":{"international":2,"popularite":-2},"news":"Voisinage : « liens fraternels », rappelle le Planalto"},{"tone":"offensive","label":"Nous parlons portugais, ils parlent espagnol, et nous avons tous raison. Je les invite à venir apprendre à jouer au football comme on le fait ici.","effects":{"popularite":4,"international":-3,"cohesion":2,"economie":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Une rencontre régionale est reportée par vexation"}],"news":"Le président aux voisins : « Venez apprendre le football »"}]},{"id":"bresil-q-culture-jeitinho","theme":"popularite","text":"On dit que le « jeitinho » — l’art de contourner les règles avec le sourire — est une seconde constitution. Êtes-vous déjà passé par le jeitinho vous-même, Chef de l’exécutif ?","answers":[{"tone":"franche","label":"Oui, comme tout le monde, et je ne m’en vante pas. Mais un pays qui s’en remet au jeitinho pour ses routes et ses écoles a un vrai problème.","effects":{"popularite":3,"cohesion":2,"assemblee":-2},"news":"Jeitinho : le président avoue y avoir déjà recouru, sourire en coin"},{"tone":"langue-de-bois","label":"Le jeitinho relève de la créativité et de la solidarité brésiliennes, dans la limite des règles qui nous gouvernent.","effects":{"popularite":2,"cohesion":-2},"news":"Jeitinho : « créativité et solidarité », selon le Planalto"},{"tone":"offensive","label":"Le jeitinho est ce qui rend ce pays supportable pour ceux qui travaillent dur. Laissons les puristes des règles écrire leurs lettres, nous irons faire les choses.","effects":{"popularite":5,"international":-3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"popularite":-2,"international":-1},"label":"Les juristes préparent une tribune"}],"news":"Le président défend le jeitinho : « Les puristes écrivent, nous faisons »"}]}]}'),u={pays:e,version:1,textes:s,institutions:n,election:t,lois:a,crises:i,missions:r,presse:o};export{i as crises,u as default,t as election,n as institutions,a as lois,r as missions,e as pays,o as presse,s as textes,l as version};
